from pathlib import Path
import sys


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected 1 match, found {count}")
    return text.replace(old, new, 1)


def main(path: str) -> None:
    p = Path(path)
    s = p.read_text(encoding="utf-8-sig")

    s = replace_once(s, 'APP_VERSION = "1.11.21"', 'APP_VERSION = "1.11.22"', 'version')
    s = replace_once(
        s,
        'DEFAULT_UI_MODE = "modern"\nUI_MODES = {"modern", "classic"}\n',
        '''DEFAULT_UI_MODE = "modern"\nUI_MODES = {"modern", "classic"}\nTUTORIAL_SETTING_KEY = "__tutorial_v2_state"\n\nTUTORIAL_TOPICS = (\n    {\n        "id": "workflow", "title": "The complete workflow", "page": "dashboard",\n        "keywords": "start beginner workflow load allocate select validate export pastel overview",\n        "body": "The normal working cycle is: 1) Load the bank CSV. 2) Review and allocate Payments and Receipts. 3) Select the rows you want to export. 4) Validate the selection. 5) Export the separate Pastel Payment and Receipt files. Always review the imported Pastel batch before processing it."\n    },\n    {\n        "id": "profiles", "title": "Company profiles", "page": "dashboard",\n        "keywords": "company profile new company separate database switch company",\n        "body": "Use one company profile per accounting workspace. Each profile keeps its own saved rules, settings, transaction history, recurring history and autosaved session. Switching profiles does not mix accounting data."\n    },\n    {\n        "id": "settings", "title": "Essential Pastel settings", "page": "settings",\n        "keywords": "settings contra bank gl vat tax type fiscal year period project",\n        "body": "Before the first export, confirm the cash-book bank GL / contra setting, VAT tax type, VAT rate, fiscal-year start month and optional project code. The cash-book bank GL is a batch/cash-book setting, not a different contra for each transaction."\n    },\n    {\n        "id": "load", "title": "Load a bank CSV", "page": "dashboard",\n        "keywords": "load bank csv statement import bank file",\n        "body": "Choose Load statement and select a supported bank CSV. The app separates outgoing Payments from incoming Receipts automatically and then applies saved rules for the active company profile."\n    },\n    {\n        "id": "payments_receipts", "title": "Payments vs Receipts", "page": "payments",\n        "keywords": "payment receipt money in money out negative positive bank amount sign",\n        "body": "Payments are money leaving the bank. Receipts are money entering the bank. In the Pastel import, receipt GL-side amounts are intentionally exported as credits so Pastel displays a positive Bank Amount on the Receipts side."\n    },\n    {\n        "id": "orange", "title": "Why is a transaction orange?", "page": "payments",\n        "keywords": "orange unassigned no gl not allocated missing account",\n        "body": "Orange means the transaction is unassigned: it does not yet have a usable GL account. Use Assign once for a statement-only allocation or create/edit a saved rule if the same stable identity should be automated in future statements."\n    },\n    {\n        "id": "green", "title": "What does green mean?", "page": "payments",\n        "keywords": "green assigned allocated status",\n        "body": "Green means a GL allocation exists. Still review the GL, description and VAT treatment before export; green means assigned, not automatically accounting-approved."\n    },\n    {\n        "id": "ambiguous", "title": "Ambiguous or conflicting rules", "page": "rules",\n        "keywords": "ambiguous conflict two rules wrong match red",\n        "body": "Ambiguous means equally strong saved rules disagree about the allocation. Resolve the conflicting saved rules before export. The app deliberately blocks ambiguous selected rows instead of guessing."\n    },\n    {\n        "id": "assign_once", "title": "Assign once vs saved rule", "page": "payments",\n        "keywords": "assign once manual save rule future statement automatic allocation",\n        "body": "Assign once changes only the current statement row. Save rule from selected teaches the app how that stable bank identity should allocate on future statements. Use a saved rule only when you are confident the identity should receive the same treatment again."\n    },\n    {\n        "id": "wrong_gl", "title": "An automatic allocation used the wrong GL", "page": "payments",\n        "keywords": "wrong gl incorrect allocation fix correct auto allocation update rule",\n        "body": "Use Correct auto-allocation. Choose a statement-only correction when this transaction is exceptional, or update the saved rule when future matching transactions should use the corrected GL/VAT/description."\n    },\n    {\n        "id": "vat", "title": "VAT and tax type", "page": "settings",\n        "keywords": "vat tax type 15 percent inclusive output input",\n        "body": "VAT-enabled rows need a valid Pastel tax type. The app calculates the VAT portion from the VAT-inclusive bank amount using the profile VAT rate, but the user remains responsible for deciding whether VAT is appropriate for that accounting transaction."\n    },\n    {\n        "id": "amount_rules", "title": "Amount-based rules", "page": "rules",\n        "keywords": "amount threshold greater less review alternative gl unusual amount",\n        "body": "A saved rule can apply an alternative GL/description when an amount condition is met, or send qualifying amounts to Review so a person allocates those transactions individually. Review mode is safer when the amount changes the accounting purpose."\n    },\n    {\n        "id": "recurring", "title": "How recurring transactions work", "page": "recurring_payments",\n        "keywords": "recurring payment receipt repeat missing recurring group identity child",\n        "body": "Recurring screens group identities that have been seen repeatedly. The group is organisational only: every child transaction can still have its own GL, VAT, description and export checkbox. Recurrence grouping does not loosen the saved-rule allocation matcher."\n    },\n    {\n        "id": "recurring_missing", "title": "A recurring transaction is missing", "page": "recurring_payments",\n        "keywords": "missing recurring not showing repeat payee name reference changing",\n        "body": "A recurring identity normally needs to be seen at least twice. Changing bank-generated references can cause otherwise similar transactions to look different; verified payee-normalisation handles known cases, but unfamiliar wording may still need review."\n    },\n    {\n        "id": "selection", "title": "Auto and Manual export selection", "page": "payments",\n        "keywords": "select auto manual additive tick checkbox clear all export selection",\n        "body": "Add Auto-Allocated and Add Manual Allocations are additive. Using both keeps both groups ticked. Use Clear All only when you intentionally want to start the export selection over."\n    },\n    {\n        "id": "validation", "title": "Validation errors", "page": "dashboard",\n        "keywords": "validate error blocked export check selected unassigned ambiguous field length",\n        "body": "Validation blocks unsafe selected rows such as unassigned transactions, ambiguous rule matches, missing VAT tax types and invalid Pastel field lengths. Resolve the error or untick the transaction before exporting."\n    },\n    {\n        "id": "export", "title": "Export to Pastel", "page": "dashboard",\n        "keywords": "export pastel csv payment receipt import cash book",\n        "body": "Export selected to Pastel creates separate Payment and Receipt CSV files plus review/validation files. Import the Payment CSV on Pastel's Payments side and the Receipt CSV on the Receipts side."\n    },\n    {\n        "id": "receipt_sign", "title": "Receipt Bank Amount is negative in Pastel", "page": "receipts",\n        "keywords": "receipt negative minus sign bank amount wrong sign money in",\n        "body": "In current builds, receipts use the corrected export sign so Pastel shows a positive Bank Amount on the Receipts side. If a receipt still shows negative, confirm the Receipt CSV was imported into Pastel's Receipts side and that the current build is being used."\n    },\n    {\n        "id": "references", "title": "Pastel references", "page": "dashboard",\n        "keywords": "reference sequence p6 r6 duplicate monthly number",\n        "body": "Final export references are generated automatically as separate monthly Payment and Receipt sequences, for example P6-0001 and R6-0001. This prevents duplicate rule-level references from being reused across exported rows."\n    },\n    {\n        "id": "autosave", "title": "Autosave and resume", "page": "dashboard",\n        "keywords": "autosave resume close quit previous session where left off",\n        "body": "When the app closes normally it saves the active profile's statement, allocations, corrections, export ticks, filters, recurring view and current page. Reopening the same profile restores that session."\n    },\n    {\n        "id": "classic", "title": "Modern vs Classic UI", "page": "dashboard",\n        "keywords": "classic old ui previous layout modern switch backwards compatible",\n        "body": "Modern and Classic UI are two views over the same company data and accounting logic. Switch at any time without migrating rules, settings, history or the current session."\n    },\n    {\n        "id": "backup", "title": "Back up and move saved rules", "page": "rules",\n        "keywords": "backup rules export import move pc migrate settings",\n        "body": "Use Saved Rules to export/import a rules backup. Settings also have transfer options. For a full migration, close the app and back up the appropriate AppData workspace after confirming which Personal or Clean build you are using."\n    },\n)\n''',
        'tutorial constants and search topics',
    )

    marker = '\n\nclass App(tk.Tk):\n'
    helper = '''\n\ndef tutorial_workspace_snapshot(store: "Store", txns=None, receipts=None) -> Dict[str, object]:\n    """Summarise the user's current progress for adaptive onboarding."""\n    txns = list(txns or [])\n    receipts = list(receipts or [])\n    all_txns = txns + receipts\n    selected = [t for t in all_txns if t.include]\n    unassigned = [t for t in selected if not t.account]\n    ambiguous = [t for t in selected if t.ambiguous]\n    assigned = [t for t in all_txns if t.account and not t.ambiguous]\n    recurring = [t for t in all_txns if t.recurring_count >= 2]\n    try:\n        rule_count = len(store.all_rules())\n    except Exception:\n        rule_count = 0\n    settings = {\n        "contra_account": (store.get_setting("contra_account", "") or "").strip(),\n        "vat_tax_type": (store.get_setting("vat_tax_type", "") or "").strip(),\n        "vat_rate": (store.get_setting("vat_rate", "15") or "15").strip(),\n        "fiscal_start_month": (store.get_setting("fiscal_start_month", "3") or "3").strip(),\n    }\n    try:\n        hist_row = store.conn.execute("SELECT COUNT(*) AS c FROM transaction_history").fetchone()\n        history_count = int(hist_row["c"] if hist_row else 0)\n    except Exception:\n        history_count = 0\n    return {\n        "loaded": bool(all_txns),\n        "payments": len(txns),\n        "receipts": len(receipts),\n        "selected": len(selected),\n        "assigned": len(assigned),\n        "unassigned": len(unassigned),\n        "ambiguous": len(ambiguous),\n        "recurring": len(recurring),\n        "rules": rule_count,\n        "history": history_count,\n        "settings_ready": bool(settings["contra_account"] or settings["vat_tax_type"]),\n        "has_activity": bool(all_txns or rule_count or history_count or settings["contra_account"] or settings["vat_tax_type"]),\n    }\n\n\ndef should_auto_start_tutorial(store: "Store") -> bool:\n    """Only auto-open onboarding in a genuinely new/empty workspace."""\n    try:\n        if (store.get_setting(TUTORIAL_SETTING_KEY, "") or "").strip():\n            return False\n        snap = tutorial_workspace_snapshot(store)\n        if snap["has_activity"]:\n            return False\n        if (store.get_setting(SESSION_SETTING_KEY, "") or "").strip():\n            return False\n        return True\n    except Exception:\n        return False\n\n\ndef adaptive_tutorial_topic_ids(snapshot: Dict[str, object]) -> List[str]:\n    """Build the shortest useful curriculum from current profile/statement state."""\n    ids = ["workflow", "profiles"]\n    if not snapshot.get("settings_ready"):\n        ids.append("settings")\n    if not snapshot.get("loaded"):\n        ids.extend(["load", "payments_receipts", "assign_once", "vat", "recurring", "selection", "validation", "export", "autosave", "classic", "backup"])\n        return ids\n    ids.append("payments_receipts")\n    if int(snapshot.get("unassigned") or 0) > 0:\n        ids.extend(["orange", "assign_once"])\n    elif int(snapshot.get("assigned") or 0) > 0:\n        ids.append("green")\n    if int(snapshot.get("ambiguous") or 0) > 0:\n        ids.append("ambiguous")\n    if int(snapshot.get("rules") or 0) == 0:\n        ids.extend(["assign_once", "vat", "amount_rules"])\n    else:\n        ids.extend(["wrong_gl", "amount_rules"])\n    if int(snapshot.get("recurring") or 0) > 0:\n        ids.append("recurring")\n    else:\n        ids.append("recurring_missing")\n    ids.extend(["selection", "validation", "export", "autosave", "classic", "backup"])\n    out = []\n    for topic_id in ids:\n        if topic_id not in out:\n            out.append(topic_id)\n    return out\n\n\ndef search_tutorial_topics(query: str) -> List[Dict[str, str]]:\n    q = normalize_text(query)\n    if not q:\n        return list(TUTORIAL_TOPICS)\n    words = [w for w in q.split() if len(w) > 1]\n    ranked = []\n    for topic in TUTORIAL_TOPICS:\n        hay = normalize_text(f"{topic['title']} {topic['keywords']} {topic['body']}")\n        score = 0\n        if q and q in hay:\n            score += 12\n        for word in words:\n            if word in hay:\n                score += 3\n            if word in normalize_text(topic["title"]):\n                score += 3\n            if word in normalize_text(topic["keywords"]):\n                score += 2\n        if score:\n            ranked.append((score, topic["title"], topic))\n    ranked.sort(key=lambda x: (-x[0], x[1]))\n    return [x[2] for x in ranked]\n'''
    s = replace_once(s, marker, helper + marker, 'adaptive tutorial helpers')

    s = replace_once(
        s,
        '''        self._build()\n        self._refresh_profile_ui()\n        self._startup_restore()\n        self.protocol("WM_DELETE_WINDOW", self.on_close)\n''',
        '''        self._build()\n        self._refresh_profile_ui()\n        self._startup_restore()\n        self.after(450, self._maybe_start_tutorial)\n        self.protocol("WM_DELETE_WINDOW", self.on_close)\n''',
        'tutorial startup scheduling',
    )

    methods_marker = '    def _configure_modern_style(self):\n'
    methods = '''    def _tutorial_topic_by_id(self, topic_id: str):\n        for topic in TUTORIAL_TOPICS:\n            if topic["id"] == topic_id:\n                return topic\n        return TUTORIAL_TOPICS[0]\n\n    def _tutorial_snapshot(self):\n        return tutorial_workspace_snapshot(self.store, self.txns, self.receipts)\n\n    def _tutorial_progress_summary(self, snap):\n        if not snap["loaded"]:\n            return f"{snap['rules']} saved rule(s) found. No statement is currently loaded."\n        return (f"Current statement: {snap['payments']} payments, {snap['receipts']} receipts, "\n                f"{snap['assigned']} assigned, {snap['unassigned']} unassigned, "\n                f"{snap['ambiguous']} ambiguous, {snap['recurring']} recurring transaction(s).")\n\n    def _maybe_start_tutorial(self):\n        if should_auto_start_tutorial(self.store):\n            self.start_tutorial(auto=True)\n\n    def start_tutorial(self, auto: bool = False):\n        old = getattr(self, "tutorial_window", None)\n        if old is not None:\n            try:\n                if old.winfo_exists():\n                    old.lift(); old.focus_force(); return\n            except Exception:\n                pass\n        self._tutorial_previous_mode = getattr(self, "ui_mode", DEFAULT_UI_MODE)\n        self._tutorial_auto = bool(auto)\n        self._tutorial_snapshot_data = self._tutorial_snapshot()\n        self._tutorial_topic_ids = adaptive_tutorial_topic_ids(self._tutorial_snapshot_data)\n        self._tutorial_index = 0\n        self._tutorial_search_mode = False\n        if getattr(self, "ui_mode", DEFAULT_UI_MODE) != "modern":\n            self._apply_ui_mode("modern", initial=True)\n\n        win = tk.Toplevel(self)\n        self.tutorial_window = win\n        win.title(f"{APP_NAME} - Tutorial & Help")\n        win.minsize(820, 560)\n        win.configure(bg="#f4f7fb")\n        win.transient(self)\n        try:\n            self.update_idletasks()\n            width, height = 940, 650\n            x = max(0, self.winfo_rootx() + (self.winfo_width() - width) // 2)\n            y = max(0, self.winfo_rooty() + (self.winfo_height() - height) // 2)\n            win.geometry(f"{width}x{height}+{x}+{y}")\n        except Exception:\n            win.geometry("940x650")\n\n        header = tk.Frame(win, bg="#0f2744", padx=22, pady=16)\n        header.pack(fill="x")\n        tk.Label(header, text="TUTORIAL & SEARCHABLE HELP", bg="#0f2744", fg="#9dd8cb", font=("Segoe UI", 9, "bold")).pack(anchor="w")\n        tk.Label(header, text="Learn what matters next - or search for a problem", bg="#0f2744", fg="#ffffff", font=("Segoe UI", 18, "bold")).pack(anchor="w", pady=(3, 0))\n\n        searchbar = tk.Frame(win, bg="#ffffff", padx=18, pady=12, highlightthickness=1, highlightbackground="#e2e8f0")\n        searchbar.pack(fill="x", padx=18, pady=(16, 8))\n        tk.Label(searchbar, text="Search help", bg="#ffffff", fg="#334155", font=("Segoe UI", 9, "bold")).pack(side="left", padx=(0, 8))\n        self.tutorial_search_var = tk.StringVar()\n        entry = ttk.Entry(searchbar, textvariable=self.tutorial_search_var)\n        entry.pack(side="left", fill="x", expand=True)\n        entry.bind("<KeyRelease>", lambda e: self._tutorial_search())\n        entry.bind("<Return>", lambda e: self._tutorial_open_first_search_result())\n        ttk.Button(searchbar, text="Clear search", command=self._tutorial_clear_search, style="Modern.TButton").pack(side="left", padx=(8, 0))\n\n        body = tk.Frame(win, bg="#f4f7fb", padx=18, pady=6)\n        body.pack(fill="both", expand=True)\n        left = tk.Frame(body, bg="#ffffff", width=255, highlightthickness=1, highlightbackground="#e2e8f0")\n        left.pack(side="left", fill="y", padx=(0, 10))\n        left.pack_propagate(False)\n        tk.Label(left, text="Recommended path / search results", bg="#ffffff", fg="#64748b", font=("Segoe UI", 8, "bold"), anchor="w", wraplength=220, justify="left").pack(fill="x", padx=12, pady=(12, 7))\n        self.tutorial_list = tk.Listbox(left, bd=0, highlightthickness=0, activestyle="none", font=("Segoe UI", 9), selectbackground="#dbeafe", selectforeground="#1d4ed8")\n        self.tutorial_list.pack(fill="both", expand=True, padx=8, pady=(0, 8))\n        self.tutorial_list.bind("<<ListboxSelect>>", lambda e: self._tutorial_list_selected())\n        self.tutorial_rescan_button = ttk.Button(left, text="Re-scan my progress", command=self._tutorial_rescan, style="Modern.TButton")\n        self.tutorial_rescan_button.pack(fill="x", padx=10, pady=(0, 10))\n\n        right = tk.Frame(body, bg="#ffffff", highlightthickness=1, highlightbackground="#e2e8f0")\n        right.pack(side="left", fill="both", expand=True)\n        top = tk.Frame(right, bg="#ffffff", padx=18, pady=14)\n        top.pack(fill="x")\n        self.tutorial_step_var = tk.StringVar()\n        self.tutorial_title_var = tk.StringVar()\n        self.tutorial_progress_var = tk.StringVar(value=self._tutorial_progress_summary(self._tutorial_snapshot_data))\n        tk.Label(top, textvariable=self.tutorial_step_var, bg="#ffffff", fg="#2563eb", font=("Segoe UI", 9, "bold")).pack(anchor="w")\n        tk.Label(top, textvariable=self.tutorial_title_var, bg="#ffffff", fg="#172033", font=("Segoe UI", 16, "bold"), wraplength=580, justify="left").pack(anchor="w", pady=(3, 6))\n        tk.Label(top, textvariable=self.tutorial_progress_var, bg="#eef6ff", fg="#334155", font=("Segoe UI", 8), wraplength=590, justify="left", padx=10, pady=7).pack(fill="x")\n        self.tutorial_body_text = tk.Text(right, wrap="word", bd=0, bg="#ffffff", fg="#334155", font=("Segoe UI", 10), padx=18, pady=10, spacing1=3, spacing3=6)\n        self.tutorial_body_text.pack(fill="both", expand=True)\n        self.tutorial_body_text.configure(state="disabled")\n\n        footer = tk.Frame(win, bg="#f4f7fb", padx=18, pady=12)\n        footer.pack(fill="x")\n        self.tutorial_skip_button = ttk.Button(footer, text="Skip tutorial", command=self._tutorial_skip, style="Modern.TButton")\n        self.tutorial_skip_button.pack(side="left")\n        ttk.Button(footer, text="Close", command=self._tutorial_close, style="Modern.TButton").pack(side="left", padx=6)\n        self.tutorial_back_button = ttk.Button(footer, text="Back", command=lambda: self._tutorial_move(-1), style="Modern.TButton")\n        self.tutorial_back_button.pack(side="right", padx=(6, 0))\n        self.tutorial_next_button = ttk.Button(footer, text="Next", command=lambda: self._tutorial_move(1), style="Accent.TButton")\n        self.tutorial_next_button.pack(side="right")\n\n        win.protocol("WM_DELETE_WINDOW", self._tutorial_close)\n        self._tutorial_fill_list()\n        self._tutorial_show_current()\n        entry.focus_set() if not auto else None\n\n    def _tutorial_current_topics(self):\n        if self._tutorial_search_mode:\n            return getattr(self, "_tutorial_search_results", [])\n        return [self._tutorial_topic_by_id(x) for x in self._tutorial_topic_ids]\n\n    def _tutorial_fill_list(self):\n        topics = self._tutorial_current_topics()\n        self.tutorial_list.delete(0, "end")\n        for idx, topic in enumerate(topics):\n            prefix = "" if self._tutorial_search_mode else f"{idx + 1}. "\n            self.tutorial_list.insert("end", prefix + topic["title"])\n        if topics:\n            self._tutorial_index = max(0, min(self._tutorial_index, len(topics) - 1))\n            self.tutorial_list.selection_clear(0, "end")\n            self.tutorial_list.selection_set(self._tutorial_index)\n            self.tutorial_list.see(self._tutorial_index)\n\n    def _tutorial_show_current(self):\n        topics = self._tutorial_current_topics()\n        if not topics:\n            self.tutorial_step_var.set("No matching help topic")\n            self.tutorial_title_var.set("Try a different search")\n            body = "Search using a short description of the problem, for example: orange transaction, wrong GL, VAT, recurring missing, receipt negative, export, autosave, or company profile."\n            self.tutorial_back_button.configure(state="disabled")\n            self.tutorial_next_button.configure(state="disabled")\n        else:\n            self._tutorial_index = max(0, min(self._tutorial_index, len(topics) - 1))\n            topic = topics[self._tutorial_index]\n            if self._tutorial_search_mode:\n                self.tutorial_step_var.set(f"Search result {self._tutorial_index + 1} of {len(topics)}")\n            else:\n                self.tutorial_step_var.set(f"Recommended step {self._tutorial_index + 1} of {len(topics)}")\n            self.tutorial_title_var.set(topic["title"])\n            body = topic["body"]\n            self.tutorial_back_button.configure(state="normal" if self._tutorial_index > 0 else "disabled")\n            if self._tutorial_search_mode:\n                self.tutorial_next_button.configure(text="Next result", state="normal" if self._tutorial_index < len(topics) - 1 else "disabled")\n            else:\n                is_last = self._tutorial_index == len(topics) - 1\n                self.tutorial_next_button.configure(text="Finish" if is_last else "Next", state="normal")\n            try:\n                if topic.get("page"):\n                    self._navigate_modern(topic["page"])\n            except Exception:\n                pass\n        self.tutorial_body_text.configure(state="normal")\n        self.tutorial_body_text.delete("1.0", "end")\n        self.tutorial_body_text.insert("1.0", body)\n        self.tutorial_body_text.configure(state="disabled")\n\n    def _tutorial_list_selected(self):\n        sel = self.tutorial_list.curselection()\n        if not sel:\n            return\n        self._tutorial_index = int(sel[0])\n        self._tutorial_show_current()\n\n    def _tutorial_move(self, delta: int):\n        topics = self._tutorial_current_topics()\n        if not topics:\n            return\n        if not self._tutorial_search_mode and delta > 0 and self._tutorial_index >= len(topics) - 1:\n            self._tutorial_finish(); return\n        new_idx = self._tutorial_index + delta\n        if 0 <= new_idx < len(topics):\n            self._tutorial_index = new_idx\n            self.tutorial_list.selection_clear(0, "end")\n            self.tutorial_list.selection_set(new_idx)\n            self.tutorial_list.see(new_idx)\n            self._tutorial_show_current()\n\n    def _tutorial_search(self):\n        query = self.tutorial_search_var.get().strip()\n        if not query:\n            self._tutorial_clear_search(); return\n        self._tutorial_search_mode = True\n        self._tutorial_search_results = search_tutorial_topics(query)\n        self._tutorial_index = 0\n        self._tutorial_fill_list()\n        self._tutorial_show_current()\n\n    def _tutorial_open_first_search_result(self):\n        if self.tutorial_search_var.get().strip():\n            self._tutorial_search()\n\n    def _tutorial_clear_search(self):\n        self.tutorial_search_var.set("")\n        self._tutorial_search_mode = False\n        self._tutorial_index = 0\n        self._tutorial_fill_list()\n        self._tutorial_show_current()\n\n    def _tutorial_rescan(self):\n        self._tutorial_snapshot_data = self._tutorial_snapshot()\n        self._tutorial_topic_ids = adaptive_tutorial_topic_ids(self._tutorial_snapshot_data)\n        self.tutorial_progress_var.set(self._tutorial_progress_summary(self._tutorial_snapshot_data))\n        self._tutorial_search_mode = False\n        self.tutorial_search_var.set("")\n        self._tutorial_index = 0\n        self._tutorial_fill_list()\n        self._tutorial_show_current()\n        self.status_var.set("Tutorial re-scanned the active profile and tailored the recommended path to the work currently completed.")\n\n    def _tutorial_record_state(self, state: str):\n        try:\n            self.store.set_setting(TUTORIAL_SETTING_KEY, state)\n        except Exception:\n            pass\n\n    def _tutorial_skip(self):\n        self._tutorial_record_state("skipped")\n        self.status_var.set("Tutorial skipped. You can run Tutorial & Help from the menu at any time.")\n        self._tutorial_close()\n\n    def _tutorial_finish(self):\n        self._tutorial_record_state("completed")\n        self.status_var.set("Tutorial completed. Tutorial & Help remains available from the menu whenever you need it.")\n        self._tutorial_close()\n\n    def _tutorial_close(self):\n        win = getattr(self, "tutorial_window", None)\n        if win is not None:\n            try:\n                win.destroy()\n            except Exception:\n                pass\n        self.tutorial_window = None\n\n'''
    s = replace_once(s, methods_marker, methods + methods_marker, 'tutorial UI and adaptive methods')

